#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    vector<int> minOperations(string boxes) {
        int n = boxes.size();
        vector<int> res(n, 0);
        int count = 0, ops = 0;

        for (int i = 0; i < n; ++i) {
            res[i] += ops;
            count += boxes[i] - '0';
            ops += count;
        }

        count = ops = 0;
        for (int i = n - 1; i >= 0; --i) {
            res[i] += ops;
            count += boxes[i] - '0';
            ops += count;
        }

        return res;
    }
};
